// --- LOGICA DE ROUBO ---
void Mimico::aoCausarDano(Personagem* atacante, Personagem* alvo, int danoCausado) {
    if (danoCausado <= 0) return;
    
    int ouroAtual = alvo->obterInventario()->obterOuro();
    if (ouroAtual <= 0) return; // Jogador já está pobre

    int roubo = GeradorAleatorio::obterInteiro(30, 80);
    if (roubo > ouroAtual) roubo = ouroAtual; // Não pode roubar mais do que o jogador tem
    
    alvo->obterInventario()->adicionarOuro(-roubo);
    ouroRoubadoTotal += roubo;
    
    // A mensagem na UI foi removida para priorizar o combate limpo
    // std::string msg = TelaCombate::margemCombate() + Aparencia::cor(Cor::AMARELO) + ">> [MIMICO]: Com uma lingua grotesca, o Mimico roubou " + std::to_string(roubo) + "G do seu bolso!" + Aparencia::cor(Cor::RESET) + "\n";
    // TelaCombate::adicionarMensagemFixa(msg);
    Aparencia::registrarLogBatalha(FuncoesDialogo::formatarMsgHabilidade("Com uma lingua grotesca, o Mimico roubou " + std::to_string(roubo) + "G do seu bolso!", Cor::AMARELO));
}

// --- BESTIARIO E DROPS ---
InfoBestiario Mimico::obterInfoBestiario() const {
    return {
        "Masmorras e Cavernas", 
        "Dentro de Baus",
        "Uma criatura magica horrenda que se disfarca de baus de tesouro para devorar aventureiros gananciosos.",
        "Mimicos digerem carne rapidamente, mas cospem os metais preciosos.",
        {"Armadura de bau", "Ouro", "Ouro Extra (Ouro roubado retornado)", FabricaItens::obterNomeDeID(ItemID::PocaoCura30)},
        4
    };
}

void Mimico::realizarDrops(Personagem* inimigo, Personagem* jogadorAtual, std::vector<std::string>& itensObtidos, int& ouroTotal, int& xpTotal)
{
    Drops::relatarEProcessarXpOuro(jogadorAtual, 150, 120 + ouroRoubadoTotal, ouroTotal, xpTotal);

    if (ouroRoubadoTotal > 0) {
         Aparencia::registrarLogBatalha(FuncoesDialogo::formatarMsgDrop("Voce recuperou " + std::to_string(ouroRoubadoTotal) + "G que haviam sido roubados!", Cor::AMARELO));
         Bestiario::instancia().registrarDrop(inimigo->obterNome(), "Ouro Extra (Ouro roubado retornado)");
    }

    Drops::darEProcessarItem(jogadorAtual, ItemID::PocaoCura30, GeradorAleatorio::obterInteiro(1, 2), itensObtidos);
    Drops::darEProcessarItem(jogadorAtual, ItemID::ArmaduraBau, 1, itensObtidos);
}
